@CrossOrigin
@RestController
@RequestMapping("/PharmacyQuery")
public class PharmacyQueryRestController extends BaseSpringRestController {
	
	public PharmacyQueryRestController( PharmacyService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Pharmacy using a UUID
     * @param		UUID pharmacyId
     * @return		Pharmacy
     */    
    @GetMapping("/load")
    public Pharmacy load( @RequestParam(required=true) UUID pharmacyId ) {
    	Pharmacy entity = null;

    	try {  
    		entity = service.getPharmacy( new PharmacyFetchOneSummary( pharmacyId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Pharmacy using Id " + pharmacyId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Pharmacy business objects
     * @return		Set<Pharmacy>
     */
    @GetMapping("/")
    public List<Pharmacy> loadAll() {                
    	List<Pharmacy> pharmacyList = null;
        
    	try {
            // load the Pharmacy
            pharmacyList = service.getAllPharmacy();
            
            if ( pharmacyList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Pharmacys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Pharmacys ", exc );
        	return null;
        }

        return pharmacyList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Pharmacy pharmacy = null;
    protected PharmacyService service = null;
    private static final Logger LOGGER = Logger.getLogger(PharmacyQueryRestController.class.getName());
    
}
